import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import LinkButton from 'flarum/common/components/LinkButton';
import extractText from 'flarum/common/utils/extractText';
import Leaderboard from '../components/Leaderboard';
const t = key => app.translator.trans(`ernestdefoe-brainstorm.forum.leaderboard.${key}`);

/** /quizzes/leaderboard — quizzes passed, across every quiz. */
export default class LeaderboardPage extends Page {
  oninit(vnode) {
    super.oninit(vnode);
    app.setTitle(extractText(t('overall')));
  }
  view() {
    return m(PageStructure, {
      className: "BrainstormLeaderboardPage",
      sidebar: () => m(IndexSidebar, null)
    }, m("div", {
      className: "BrainstormIndexPage-head"
    }, m("h2", {
      className: "BrainstormIndexPage-title"
    }, t('overall')), m(LinkButton, {
      className: "Button",
      icon: "fas fa-arrow-left",
      href: app.route('brainstorm.index')
    }, t('back'))), m("p", {
      className: "helpText"
    }, t('overall_help')), m(Leaderboard, null));
  }
}
flarum.reg.add('ernestdefoe-brainstorm', 'forum/pages/LeaderboardPage', LeaderboardPage);